<?php
declare(strict_types=1);

function sf_songbook_json(array $v): string { return json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) ?: '[]'; }
function sf_songbook_decode(mixed $v,array $fallback=[]): array { $d=is_array($v)?$v:json_decode((string)$v,true);return is_array($d)?$d:$fallback; }
function sf_songbook_track(string $trackId): ?array { foreach(sf_catalog() as $t)if((string)($t['id']??'')===$trackId)return $t;return null; }
function sf_songbook_public_track(string $trackId): ?array {
    if(function_exists('sf_seo_public_track'))return sf_seo_public_track($trackId);
    $t=sf_songbook_track($trackId);if(!$t||($t['public_visible']??true)===false||in_array((string)($t['state']??''),['draft','private','archived'],true))return null;return $t;
}
function sf_songbook_lines(string $lyrics): array { return preg_split('/\R/u',str_replace(["\r\n","\r"],"\n",$lyrics)) ?: []; }

function sf_songbook_ensure_schema(): void {
    static $done=false;if($done)return;$pdo=sf_db();$driver=(string)(sf_db_config()['driver']??'');
    if($driver==='sqlite'){
      $pdo->exec("CREATE TABLE IF NOT EXISTS songbooks (track_id TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'draft',language TEXT NOT NULL DEFAULT 'en',sections_json TEXT NOT NULL DEFAULT '[]',annotations_json TEXT NOT NULL DEFAULT '[]',show_credits INTEGER NOT NULL DEFAULT 1,notes TEXT NOT NULL DEFAULT '',created_by INTEGER NULL,published_at TEXT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL)");
      $pdo->exec("CREATE INDEX IF NOT EXISTS idx_songbooks_status ON songbooks(status,updated_at)");
      $pdo->exec("CREATE TABLE IF NOT EXISTS songbook_events (id INTEGER PRIMARY KEY AUTOINCREMENT,track_id TEXT NOT NULL,event_type TEXT NOT NULL,user_id INTEGER NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL)");
      $pdo->exec("CREATE INDEX IF NOT EXISTS idx_songbook_events_track ON songbook_events(track_id,event_type,created_at)");
    }else{
      $pdo->exec("CREATE TABLE IF NOT EXISTS songbooks (track_id VARCHAR(160) NOT NULL PRIMARY KEY,status VARCHAR(32) NOT NULL DEFAULT 'draft',language VARCHAR(24) NOT NULL DEFAULT 'en',sections_json LONGTEXT NOT NULL,annotations_json LONGTEXT NOT NULL,show_credits TINYINT(1) NOT NULL DEFAULT 1,notes LONGTEXT NOT NULL,created_by BIGINT UNSIGNED NULL,published_at VARCHAR(40) NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL,INDEX idx_songbooks_status(status,updated_at),CONSTRAINT fk_songbook_admin FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
      $pdo->exec("CREATE TABLE IF NOT EXISTS songbook_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,track_id VARCHAR(160) NOT NULL,event_type VARCHAR(40) NOT NULL,user_id BIGINT UNSIGNED NULL,detail_json LONGTEXT NOT NULL,created_at VARCHAR(40) NOT NULL,INDEX idx_songbook_events_track(track_id,event_type,created_at),CONSTRAINT fk_songbook_event_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }$done=true;
}
function sf_songbook_clean_sections(array $rows,int $lineCount): array {
    $out=[];foreach($rows as $r){if(!is_array($r))continue;$label=sf_clean_text($r['label']??'',80);$start=max(1,(int)($r['start_line']??0));$end=max($start,(int)($r['end_line']??$start));if($label===''||$start>$lineCount||$end>$lineCount)continue;$out[]=['label'=>$label,'start_line'=>$start,'end_line'=>$end];if(count($out)>=80)break;}usort($out,fn($a,$b)=>$a['start_line']<=>$b['start_line']);return $out;
}
function sf_songbook_clean_annotations(array $rows,int $lineCount): array {
    $out=[];foreach($rows as $r){if(!is_array($r))continue;$line=max(1,(int)($r['line']??0));$note=sf_clean_text($r['note']??'',1000);if($note===''||$line>$lineCount)continue;$out[]=['line'=>$line,'note'=>$note];if(count($out)>=160)break;}usort($out,fn($a,$b)=>$a['line']<=>$b['line']);return $out;
}
function sf_songbook_get(string $trackId,bool $publicOnly=false): ?array {
    sf_songbook_ensure_schema();$q=sf_db()->prepare('SELECT * FROM songbooks WHERE track_id=? LIMIT 1');$q->execute([$trackId]);$r=$q->fetch();if(!$r)return null;$track=sf_songbook_track($trackId);if(!$track)return null;
    $r['show_credits']=!empty($r['show_credits']);$r['sections']=sf_songbook_decode($r['sections_json']??'',[]);$r['annotations']=sf_songbook_decode($r['annotations_json']??'',[]);unset($r['sections_json'],$r['annotations_json']);$r['track']=$track;$r['readiness']=sf_songbook_readiness($r);
    if($publicOnly&&(($r['status']??'')!=='published'||empty($r['readiness']['ready'])||!sf_songbook_public_track($trackId)))return null;return $r;
}
function sf_songbook_readiness(array $row): array {
    $track=(array)($row['track']??sf_songbook_track((string)($row['track_id']??''))??[]);$lyrics=trim((string)($track['lyrics']??''));$lines=sf_songbook_lines($lyrics);$checks=[];$add=function(string $key,bool $ok,string $detail)use(&$checks){$checks[]=['key'=>$key,'ok'=>$ok,'detail'=>$detail];};
    $add('track',!empty($track['id']),'Canonical track exists.');$add('public_track',!empty($track['id'])&&sf_songbook_public_track((string)$track['id'])!==null,'Track must be public before Songbook publication.');$add('lyrics',$lyrics!=='','Canonical Catalog lyrics are required.');$lang=(string)($row['language']??'');$add('language',(bool)preg_match('/^[a-z]{2,3}(?:-[A-Z]{2})?$/',$lang),'Use a language code such as en or en-US.');$sections=(array)($row['sections']??[]);$add('sections',count($sections)>0,'Add at least one verse/chorus/bridge section.');$bad=false;foreach($sections as $s)if((int)($s['start_line']??0)<1||(int)($s['end_line']??0)<(int)($s['start_line']??0)||(int)($s['end_line']??0)>count($lines))$bad=true;$add('section_ranges',!$bad,'Section line ranges must stay inside the canonical lyrics.');
    $passed=count(array_filter($checks,fn($c)=>!empty($c['ok'])));$blockers=array_values(array_map(fn($c)=>(string)$c['detail'],array_filter($checks,fn($c)=>empty($c['ok']))));return ['ready'=>!$blockers,'score'=>count($checks)?(int)round($passed*100/count($checks)):0,'checks'=>$checks,'blockers'=>$blockers,'line_count'=>count($lines)];
}
function sf_songbook_save(array $raw,int $adminId): array {
    sf_songbook_ensure_schema();$trackId=sf_clean_text($raw['track_id']??'',160);$track=sf_songbook_track($trackId);if(!$track)throw new InvalidArgumentException('Track not found.');$status=(string)($raw['status']??'draft');if(!in_array($status,['draft','published','archived'],true))throw new InvalidArgumentException('Invalid Songbook status.');$language=sf_clean_text($raw['language']??'en',24);$lyrics=(string)($track['lyrics']??'');$lineCount=count(sf_songbook_lines($lyrics));$sections=sf_songbook_clean_sections((array)($raw['sections']??[]),$lineCount);$annotations=sf_songbook_clean_annotations((array)($raw['annotations']??[]),$lineCount);$existing=sf_songbook_get($trackId,false);$candidate=array_merge($existing?:[],['track_id'=>$trackId,'status'=>$status,'language'=>$language,'sections'=>$sections,'annotations'=>$annotations,'show_credits'=>!empty($raw['show_credits']),'track'=>$track]);if($status==='published'){$ready=sf_songbook_readiness($candidate);if(empty($ready['ready']))throw new RuntimeException('Songbook is blocked: '.implode(' ',array_slice($ready['blockers'],0,5)));}
    $now=gmdate('c');$published=$status==='published'?((string)($existing['published_at']??'')?:$now):null;$q=sf_db()->prepare("INSERT INTO songbooks(track_id,status,language,sections_json,annotations_json,show_credits,notes,created_by,published_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(track_id) DO UPDATE SET status=excluded.status,language=excluded.language,sections_json=excluded.sections_json,annotations_json=excluded.annotations_json,show_credits=excluded.show_credits,notes=excluded.notes,published_at=excluded.published_at,updated_at=excluded.updated_at");
    if((string)(sf_db_config()['driver']??'')!=='sqlite')$q=sf_db()->prepare("INSERT INTO songbooks(track_id,status,language,sections_json,annotations_json,show_credits,notes,created_by,published_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),language=VALUES(language),sections_json=VALUES(sections_json),annotations_json=VALUES(annotations_json),show_credits=VALUES(show_credits),notes=VALUES(notes),published_at=VALUES(published_at),updated_at=VALUES(updated_at)");
    $q->execute([$trackId,$status,$language,sf_songbook_json($sections),sf_songbook_json($annotations),!empty($raw['show_credits'])?1:0,sf_clean_text($raw['notes']??'',8000),$adminId?:null,$published,$existing['created_at']??$now,$now]);return sf_songbook_get($trackId,false)?:throw new RuntimeException('Songbook could not be saved.');
}
function sf_songbook_public_payload(string $trackId): ?array {
    $r=sf_songbook_get($trackId,true);if(!$r)return null;$t=(array)$r['track'];$lyrics=(string)($t['lyrics']??'');$lines=sf_songbook_lines($lyrics);$annotations=[];foreach((array)$r['annotations'] as $a)$annotations[(int)$a['line']][]=(string)$a['note'];$sections=[];foreach((array)$r['sections'] as $s){$start=(int)$s['start_line'];$end=(int)$s['end_line'];$sectionLines=[];for($i=$start;$i<=$end;$i++)$sectionLines[]=['line'=>$i,'text'=>(string)($lines[$i-1]??''),'annotations'=>$annotations[$i]??[]];$sections[]=['label'=>(string)$s['label'],'start_line'=>$start,'end_line'=>$end,'lines'=>$sectionLines];}
    $m=(array)($t['metadata']??[]);$credits=[];if(!empty($r['show_credits'])){foreach([['Words by',$m['words_by']??''],['Music by',$m['music_by']??''],['Publisher',$m['publisher']??'']] as [$label,$value])if(trim((string)$value)!=='')$credits[]=['label'=>$label,'value'=>(string)$value];}
    return ['track_id'=>$trackId,'title'=>(string)($t['title']??$trackId),'release'=>(string)($t['release']??''),'language'=>(string)$r['language'],'sections'=>$sections,'credits'=>$credits,'published_at'=>$r['published_at'],'updated_at'=>$r['updated_at']];
}
function sf_songbook_list_public(): array { sf_songbook_ensure_schema();$ids=sf_db()->query("SELECT track_id FROM songbooks WHERE status='published' ORDER BY updated_at DESC")->fetchAll(PDO::FETCH_COLUMN);$out=[];foreach($ids as $id){$p=sf_songbook_public_payload((string)$id);if($p)$out[]=$p;}return $out; }
function sf_songbook_event(string $trackId,string $eventType,int $userId=0,array $detail=[]): void { if(!in_array($eventType,['view','section_open','annotation_open','share'],true)||!sf_songbook_get($trackId,true))return;$safe=[];foreach(array_slice($detail,0,5,true) as $k=>$v)$safe[sf_clean_text((string)$k,50)]=is_scalar($v)?sf_clean_text((string)$v,160):'';sf_db()->prepare('INSERT INTO songbook_events(track_id,event_type,user_id,detail_json,created_at) VALUES(?,?,?,?,?)')->execute([$trackId,$eventType,$userId?:null,sf_songbook_json($safe),gmdate('c')]); }
function sf_songbook_metrics(int $days=30): array { sf_songbook_ensure_schema();$since=gmdate('c',time()-max(1,min(365,$days))*86400);$q=sf_db()->prepare('SELECT event_type,COUNT(*) total FROM songbook_events WHERE created_at>=? GROUP BY event_type');$q->execute([$since]);$events=[];foreach($q->fetchAll() as $r)$events[(string)$r['event_type']]=(int)$r['total'];return ['days'=>$days,'events'=>$events,'published'=>(int)sf_db()->query("SELECT COUNT(*) FROM songbooks WHERE status='published'")->fetchColumn(),'drafts'=>(int)sf_db()->query("SELECT COUNT(*) FROM songbooks WHERE status='draft'")->fetchColumn()]; }
function sf_songbook_agent_context(string $query,int $limit=4): string {
    $terms=array_values(array_filter(preg_split('/[^a-z0-9]+/i',strtolower($query))?:[],fn($x)=>strlen($x)>2));$score=function(string $text)use($terms){$t=strtolower($text);$n=0;foreach($terms as $w)if(str_contains($t,$w))$n++;return $n;};$rows=sf_songbook_list_public();usort($rows,fn($a,$b)=>$score($b['title'].' '.json_encode($b['sections']))<=>$score($a['title'].' '.json_encode($a['sections'])));$out=[];foreach($rows as $r){$flat=[];foreach($r['sections'] as $s)foreach($s['lines'] as $l)if(trim((string)$l['text'])!=='')$flat[]=(string)$l['text'];$hay=$r['title'].' '.implode(' ',$flat);if($terms&&$score($hay)<1)continue;$out[]='- '.$r['title'].' | '.substr(implode(' / ',$flat),0,1000);if(count($out)>=$limit)break;}return $out?"PUBLISHED SONGBOOK\n".implode("\n",$out):'';
}
